const C=window.CONTENT,main=document.querySelector('main'),modal=document.querySelector('dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',timeZone:'Europe/Istanbul'}).format(new Date(d));
function release(i){if(!C.startDate)return null;return new Date(+new Date(C.startDate)+(+new Date(C.finalDate)-+new Date(C.startDate))*i/14)}
function unlocked(i){return C.startDate&&Date.now()>=+release(i)}
function home(){return `<section class="hero"><div class="hero-text"><span class="eyebrow">Sadece ikimize ait bir yer</span><h1>Biraz sen,<br>biraz ben,<br><em>bir dolu biz.</em></h1><p>En sevdiğim hikâye, seninle olanı.<br>Anılarımızı, küçük mutluluklarımızı ve henüz yazılmamış sayfalarımızı buraya sakladım.</p><div class="actions"><a class="btn" href="#story">Hikâyemize göz at <span>↗</span></a><a class="btn secondary" href="#album">Anılara dal ♡</a></div><span class="small-note">psst… burada küçük sürprizler saklı.</span></div><div class="hero-art"><div><img src="assets/rabbits-meadow.png" alt="Papatya tarlasında yıldızları izleyen iki minik tavşan"><div class="art-caption">aynı gökyüzünün altında, hep yan yana.</div></div><div class="tiny-note">en sevdiğim yer:<br>senin yanın ♡</div></div></section><div class="divider" aria-hidden="true">✧ ♡ ✧</div><div class="section-head"><div><span class="eyebrow">Bugün nereye gidelim?</span><h2>Küçük dünyamızın köşeleri</h2></div></div><section class="tiles"><a class="tile" href="#story"><span class="symbol">✦</span><span class="corner">15 bölüm ↗</span><h3>Bizim çizgi romanımız</h3><p>Her yeni sayfada, biraz daha biz.</p></a><a class="tile" href="#album"><span class="symbol">♡</span><span class="corner">Anı kutusu ↗</span><h3>İyi ki bu anlar var</h3><p>Bir fotoğraf, bin güzel his.</p></a><button class="tile" id="letter" style="text-align:left;color:inherit"><span class="symbol">✉</span><span class="corner">Sana özel ↗</span><h3>Bir küçük not bıraktım</h3><p>Açmak için kalbine dokunman yeter.</p></button></section><div class="banner"><div><strong>En güzel sayfayı sona sakladım ♡</strong><p>${C.startDate?'Hikâyemiz başladı. Her bölüm kendi gününde açılacak.':'Hikâyemiz hazırlanıyor. İlk sayfayla birlikte yolculuğumuz başlayacak.'}</p></div><div class="date">3 Kasım 2026<small>Final bölümümüz</small></div></div>`}
function story(){return `<div class="page-heading"><span class="eyebrow">Başrolünde sen ve ben</span><h1>Bizim <em>hikâyemiz.</em></h1><p>On beş bölüm, bir minik evren. ${C.startDate?'Yeni sayfalar kendi gününde açılır.':'İlk sayfalar hazırlanıyor; yolculuğumuz yakında başlayacak.'}</p></div><section class="chapters" aria-label="Çizgi roman bölümleri">${Array.from({length:15},(_,i)=>{const chapter=C.chapters[i],ready=chapter?.pages?.length;return `<button class="chapter" data-chapter="${i}"><div class="cover"><span>${unlocked(i)&&ready?'♡':'♧'}</span><b>${String(i+1).padStart(2,'0')}</b><span>${i===14?'Büyük final':'Bizim hikâyemiz'}</span></div><div class="chapter-info"><strong>${i===14?'15. Bölüm · Final':`${i+1}. Bölüm`}</strong><small>${!C.startDate?(i===14?'3 Kasım · Final':'Yakında'):!unlocked(i)?fmt(release(i))+' · Kilitli':ready?'Okumaya hazır ♡':'Sayfaları hazırlanıyor'}</small></div></button>`}).join('')}</section><div class="banner"><p>Her hikâyenin bir zamanı var. Bizimkinin en güzel sonu da 3 Kasım’da.</p><span>♡</span></div>`}
function album(){return `<div class="page-heading"><span class="eyebrow">Kalbimin fotoğraf rulosu</span><h1>İyi ki <em>biz.</em></h1><p>Bazı anlar geçer. Hissettirdikleri hep kalır.<br>Fotoğraflara dokun, o güne geri dön.</p></div>${C.photos.length?`<section class="album-grid">${C.photos.map((p,i)=>`<button class="polaroid" data-photo="${i}"><img src="${esc(p.src)}" alt="${esc(p.caption)}" loading="lazy"><p>${esc(p.caption)} ♡</p></button>`).join('')}</section>`:`<div class="empty-album"><div class="big">♡</div><h2>Anılarımıza yer açtım.</h2><p>Fotoğraflarımız buraya geldiğinde, her biri bu defterin bir parçası olacak. En güzel karelerimiz için bu sayfa bizi bekliyor.</p></div>`}<div class="divider">✧ ♡ ✧</div>`}
function render(){const page=location.hash.slice(1)||'home';main.innerHTML=page==='story'?story():page==='album'?album():home();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));window.scrollTo(0,0)}
function show(html){document.querySelector('#modal-content').innerHTML=html;modal.showModal()}
function note(){show(`<div class="message"><span class="eyebrow">Sana bir küçük not</span><h2>İyi ki yollarımız<br><em>birbirine çıktı.</em></h2><p>Bu küçük evrendeki her şey, yüzünde bir gülümseme görmek için.<br><br>Birlikte biriktirdiğimiz anılar ve bizi bekleyen bütün güzel günler için…<br><br>Bu hikâyenin en sevdiğim kahramanı sensin.</p><span>♡</span></div>`)}
function hearts(x=innerWidth/2,y=innerHeight/2){for(let i=0;i<12;i++){let e=document.createElement('span');e.className='particle';e.textContent=['♡','✧','🌼'][i%3];e.style.cssText=`left:${x}px;top:${y}px;color:#df7caa;--dx:${(Math.random()-.5)*260}px`;document.body.appendChild(e);setTimeout(()=>e.remove(),1600)}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='letter')note();if(b.classList.contains('heart-button')){hearts(e.clientX,e.clientY);const t=document.querySelector('#toast');t.textContent='Biraz daha sevgi, sırf senin için ♡';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}if(b.id==='surprise'){hearts();show('<span style="font-size:55px">🌼</span><h2>Bir papatya tuttum senin için.</h2><p>Son yaprağında da aynı şey yazıyor:<br><strong>Çok seviyor. ♡</strong></p>')}if(b.dataset.chapter!==undefined){const i=+b.dataset.chapter,chapter=C.chapters[i];if(!C.startDate)show('<h2>İlk sayfamız henüz yazılıyor ♡</h2><p>Hikâyemiz hazır olduğunda bölüm takvimi başlayacak.<br>Finalimiz 3 Kasım’da.</p>');else if(!unlocked(i))show(`<h2>Biraz merak güzel şey…</h2><p>${i+1}. bölüm ${fmt(release(i))} tarihinde açılacak. ♡</p>`);else if(!chapter?.pages?.length)show('<h2>Bu bölümün sayfaları hazırlanıyor.</h2><p>Çok yakında burada buluşacağız. ♡</p>');else show(`<div class="reader"><h2>${i+1}. Bölüm</h2>${chapter.pages.map((p,j)=>`<img src="${esc(p)}" alt="${i+1}. bölüm, ${j+1}. sayfa">`).join('')}<button class="btn" id="read-done">Okudum ♡</button></div>`)}if(b.dataset.photo!==undefined){const p=C.photos[+b.dataset.photo];show(`<img src="${esc(p.src)}" alt="${esc(p.caption)}"><h2>${esc(p.caption)}</h2>`)}if(b.id==='read-done'){modal.close();hearts()}if(b.classList.contains('close'))modal.close()});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});window.addEventListener('hashchange',render);render();setInterval(()=>{if(location.hash==='#story'&&!modal.open)render()},60000);
